    try {
      const parsed = JSON.parse(script.textContent);
      if (!Array.isArray(parsed)) return [];
      return parsed.map(normalizeSpotlightCandidate).filter(Boolean);
    } catch (error) {
      return [];
    }
  }

  function buildCandidateOrder(candidates) {
    if (candidates.length <= 1) return candidates.slice();

    const freshnessWindow = Math.min(RANDOM_WINDOW_SIZE, candidates.length);
    const freshCandidates = shuffle(candidates.slice(0, freshnessWindow));
    const olderCandidates = candidates.slice(freshnessWindow);

    return freshCandidates.concat(olderCandidates);
  }

  function applyCandidate(image, candidate) {
    image.src = candidate.src;

    if (candidate.srcset) {
      image.srcset = candidate.srcset;
    } else {
      image.removeAttribute('srcset');
    }

    if (candidate.alt) {
      image.alt = candidate.alt;
    }

    if (candidate.width) {
      image.width = candidate.width;
    }

    if (candidate.height) {
      image.height = candidate.height;
    }

    image.dataset.homepageCollectionImageKey = candidate.key;
    image.dataset.homepageCollectionImageSrc = candidate.src;
  }

  function applySpotlightCandidate(card, candidate) {
    const image = card.querySelector(SPOTLIGHT_IMAGE_SELECTOR);
    const mediaLink = card.querySelector('[data-homepage-spotlight-link="media"]');
    const titleLink = card.querySelector('[data-homepage-spotlight-link="title"]');
    const ctaLink = card.querySelector('[data-homepage-spotlight-link="cta"]');
    const caption = card.querySelector(SPOTLIGHT_CAPTION_SELECTOR);
    const price = card.querySelector(SPOTLIGHT_PRICE_SELECTOR);

    if (image) {
      image.src = candidate.imageSrc;

      if (candidate.imageSrcset) {
        image.srcset = candidate.imageSrcset;
      } else {
        image.removeAttribute('srcset');
      }

      if (candidate.imageAlt) {
        image.alt = candidate.imageAlt;
      }

      if (candidate.imageWidth) {
        image.width = candidate.imageWidth;
      }

      if (candidate.imageHeight) {
        image.height = candidate.imageHeight;
      }

      image.dataset.homepageCollectionImageKey = candidate.imageKey;
      image.dataset.homepageCollectionImageSrc = candidate.imageSrc;
    }

    [mediaLink, titleLink, ctaLink].forEach((link) => {
      if (link) link.href = candidate.url;
    });

    if (titleLink && candidate.title) {
      titleLink.textContent = candidate.title;
    }

    if (caption) {
      if (candidate.caption) {
        caption.textContent = candidate.caption;
        caption.hidden = false;
      } else {
        caption.textContent = '';
        caption.hidden = true;
      }
    }

    if (price && candidate.priceHtml) {
      price.innerHTML = candidate.priceHtml;
    }

    card.dataset.analyticsProductId = String(candidate.productId);
    card.dataset.analyticsVariantId = candidate.variantId ? String(candidate.variantId) : '';
    card.dataset.analyticsHandle = candidate.handle;
    card.dataset.analyticsTitle = candidate.title;
    card.dataset.analyticsVendor = candidate.vendor;
    card.dataset.analyticsVariant = candidate.variant;
    card.dataset.analyticsPriceCents = String(candidate.priceCents || 0);
    card.dataset.analyticsCategory1 = candidate.category1;
    card.dataset.analyticsSubcategory = candidate.subcategory;
    card.dataset.analyticsSubcategory2 = candidate.subcategory2;
    card.dataset.analyticsType = candidate.type;
    card.dataset.analyticsStyle = candidate.style;
    card.dataset.analyticsPattern = candidate.pattern;
  }

  function reserveExistingImage(image, usedKeys, usedSrcs) {
    const existingKey = String(image.dataset.homepageCollectionImageKey || '').trim();
    const existingSrc = String(image.currentSrc || image.src || '').trim();

    if (existingKey) usedKeys.add(existingKey);
    if (existingSrc) usedSrcs.add(existingSrc);
  }

  function reserveImages(root, selector, usedKeys, usedSrcs) {
    root.querySelectorAll(selector).forEach((image) => {
      reserveExistingImage(image, usedKeys, usedSrcs);
    });
  }

  function reserveStaticHomepageImages(root, usedKeys, usedSrcs) {
    reserveImages(root, STATIC_RESERVED_IMAGE_SELECTOR, usedKeys, usedSrcs);
  }

  function reserveHomepageCollectionImages(root, usedKeys, usedSrcs) {
    root.querySelectorAll(CARD_SELECTOR).forEach((card) => {
      const image = card.querySelector(IMAGE_SELECTOR);
      if (!image) return;

      reserveExistingImage(image, usedKeys, usedSrcs);

      const existingKey = String(image.dataset.homepageCollectionImageKey || '').trim();
      if (!existingKey.startsWith('asset-')) return;

      parseCandidates(card).forEach((candidate) => {
        if (candidate.key.startsWith('asset-')) return;
        usedKeys.add(candidate.key);
        usedSrcs.add(candidate.src);
      });
    });
  }

  function refreshHomepageCollectionImages(root = document) {
    const cards = Array.from(root.querySelectorAll(CARD_SELECTOR));
    if (!cards.length) return;

    const usedKeys = new Set();
    const usedSrcs = new Set();
    reserveStaticHomepageImages(root, usedKeys, usedSrcs);

    cards.forEach((card) => {
      const image = card.querySelector(IMAGE_SELECTOR);
      if (!image) return;

      const candidates = buildCandidateOrder(parseCandidates(card));
      if (!candidates.length) {
        reserveExistingImage(image, usedKeys, usedSrcs);
        return;
      }

      const selectedCandidate =
        candidates.find((candidate) => !usedKeys.has(candidate.key) && !usedSrcs.has(candidate.src)) ||
        candidates.find((candidate) => !usedSrcs.has(candidate.src)) ||
        candidates.find((candidate) => !usedKeys.has(candidate.key)) ||
        candidates[0];

      applyCandidate(image, selectedCandidate);
      usedKeys.add(selectedCandidate.key);
      usedSrcs.add(selectedCandidate.src);
    });
  }

  function refreshHomepageSpotlightProducts(root = document) {
    const cards = Array.from(root.querySelectorAll(SPOTLIGHT_CARD_SELECTOR));
    if (!cards.length) return;

    const usedKeys = new Set();
    const usedSrcs = new Set();
    const usedProductIds = new Set();
    reserveStaticHomepageImages(root, usedKeys, usedSrcs);
    reserveHomepageCollectionImages(root, usedKeys, usedSrcs);

    cards.forEach((card) => {
      const image = card.querySelector(SPOTLIGHT_IMAGE_SELECTOR);
      const candidates = buildCandidateOrder(parseSpotlightCandidates(card));

      if (!candidates.length) {
        if (image) reserveExistingImage(image, usedKeys, usedSrcs);
        const existingProductId = Number(card.dataset.analyticsProductId) || 0;
        if (existingProductId) usedProductIds.add(existingProductId);
        return;
      }

      const selectedCandidate =
        candidates.find(
          (candidate) =>
            !usedProductIds.has(candidate.productId) &&
            !usedKeys.has(candidate.imageKey) &&
            !usedSrcs.has(candidate.imageSrc)
        ) ||
        candidates.find(
          (candidate) => !usedProductIds.has(candidate.productId) && !usedKeys.has(candidate.imageKey)
        ) ||
        candidates.find((candidate) => !usedProductIds.has(candidate.productId)) ||
        candidates.find((candidate) => !usedKeys.has(candidate.imageKey) && !usedSrcs.has(candidate.imageSrc)) ||
        candidates[0];

      applySpotlightCandidate(card, selectedCandidate);
      usedProductIds.add(selectedCandidate.productId);
      usedKeys.add(selectedCandidate.imageKey);
      usedSrcs.add(selectedCandidate.imageSrc);
    });
  }

  function onReady(callback) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', callback, { once: true });
      return;
    }

    callback();
  }

  onReady(() => {
    refreshHomepageCollectionImages();
    refreshHomepageSpotlightProducts();
  });

  document.addEventListener('shopify:section:load', (event) => {
    refreshHomepageCollectionImages(event.target.ownerDocument || document);
    refreshHomepageSpotlightProducts(event.target.ownerDocument || document);
  });
})();

class PredictiveSearch extends SearchForm {
  constructor() {
    super();
    this.cachedResults = {};
    this.predictiveSearchResults = this.querySelector('[data-predictive-search]');
    this.allPredictiveSearchInstances = document.querySelectorAll('predictive-search');
    this.isOpen = false;
    this.abortController = new AbortController();
    this.searchTerm = '';

    this.setupEventListeners();
  }

  setupEventListeners() {
    this.input.addEventListener('focus', this.onFocus.bind(this));
    this.addEventListener('focusout', this.onFocusOut.bind(this));
    this.addEventListener('keyup', this.onKeyup.bind(this));
    this.addEventListener('keydown', this.onKeydown.bind(this));
  }

  getQuery() {
    return this.input.value.trim();
  }

  onChange() {
    super.onChange();
    const newSearchTerm = this.getQuery();
    if (!this.searchTerm || !newSearchTerm.startsWith(this.searchTerm)) {
      // Remove the results when they are no longer relevant for the new search term
      // so they don't show up when the dropdown opens again
      this.querySelector('#predictive-search-results-groups-wrapper')?.remove();
    }

    // Update the term asap, don't wait for the predictive search query to finish loading
    this.updateSearchForTerm(this.searchTerm, newSearchTerm);

    this.searchTerm = newSearchTerm;

    if (!this.searchTerm.length) {
      this.close(true);
      return;
    }

    this.getSearchResults(this.searchTerm);
  }

  onFormSubmit(event) {
    if (!this.getQuery().length) {
      event.preventDefault();
      return;
    }

    if (this.querySelector('[aria-selected="true"] a')) {
      event.preventDefault();
      return;
    }

    super.onFormSubmit(event);
  }

  onFormReset(event) {
    super.onFormReset(event);
    if (super.shouldResetForm()) {
      this.searchTerm = '';
      this.abortController.abort();
      this.abortController = new AbortController();
      this.closeResults(true);
    }
  }

  onFocus() {
    const currentSearchTerm = this.getQuery();

    if (!currentSearchTerm.length) return;

    if (this.searchTerm !== currentSearchTerm) {
      // Search term was changed from other search input, treat it as a user change
      this.onChange();
    } else if (this.getAttribute('results') === 'true') {
      this.open();
    } else {
      this.getSearchResults(this.searchTerm);
    }
  }

  onFocusOut() {
    setTimeout(() => {
      if (!this.contains(document.activeElement)) this.close();
    });
  }

  onKeyup(event) {
    if (!this.getQuery().length) this.close(true);
    event.preventDefault();

    switch (event.code) {
      case 'ArrowUp':
        this.switchOption('up');
        break;
      case 'ArrowDown':
        this.switchOption('down');
        break;
      case 'Enter':
        this.selectOption();
        break;
    }
  }

  onKeydown(event) {
    // Prevent the cursor from moving in the input when using the up and down arrow keys
    if (event.code === 'ArrowUp' || event.code === 'ArrowDown') {
      event.preventDefault();
    }
  }

  updateSearchForTerm(previousTerm, newTerm) {
    const searchForTextElement = this.querySelector('[data-predictive-search-search-for-text]');
    const currentButtonText = searchForTextElement?.innerText;
    if (currentButtonText) {
      if (currentButtonText.match(new RegExp(previousTerm, 'g')).length > 1) {
        // The new term matches part of the button text and not just the search term, do not replace to avoid mistakes
        return;
      }
      const newButtonText = currentButtonText.replace(previousTerm, newTerm);
      searchForTextElement.innerText = newButtonText;
    }
  }

  switchOption(direction) {
    if (!this.getAttribute('open')) return;

    const moveUp = direction === 'up';
    const selectedElement = this.querySelector('[aria-selected="true"]');

    // Filter out hidden elements (duplicated page and article resources) thanks
    // to this https://developer.mozilla.org/en-US/docs/Web/API/HTMLElement/offsetParent
    const allVisibleElements = Array.from(this.querySelectorAll('li, button.predictive-search__item')).filter(
      (element) => element.offsetParent !== null
    );
    let activeElementIndex = 0;

    if (moveUp && !selectedElement) return;

    let selectedElementIndex = -1;
    let i = 0;

    while (selectedElementIndex === -1 && i <= allVisibleElements.length) {
      if (allVisibleElements[i] === selectedElement) {
        selectedElementIndex = i;
      }
      i++;
    }

    this.statusElement.textContent = '';

    if (!moveUp && selectedElement) {
      activeElementIndex = selectedElementIndex === allVisibleElements.length - 1 ? 0 : selectedElementIndex + 1;
    } else if (moveUp) {
      activeElementIndex = selectedElementIndex === 0 ? allVisibleElements.length - 1 : selectedElementIndex - 1;
    }

    if (activeElementIndex === selectedElementIndex) return;

    const activeElement = allVisibleElements[activeElementIndex];

    activeElement.setAttribute('aria-selected', true);
    if (selectedElement) selectedElement.setAttribute('aria-selected', false);

    this.input.setAttribute('aria-activedescendant', activeElement.id);
  }

  selectOption() {
    const selectedOption = this.querySelector('[aria-selected="true"] a, button[aria-selected="true"]');

    if (selectedOption) selectedOption.click();
  }

  getSearchResults(searchTerm) {
    const queryKey = searchTerm.replace(' ', '-').toLowerCase();
    this.setLiveRegionLoadingState();

    if (this.cachedResults[queryKey]) {
      this.renderSearchResults(this.cachedResults[queryKey]);
      return;
    }

    const searchParams = new URLSearchParams({
      q: searchTerm,
      section_id: 'predictive-search',
      'resources[type]': 'product,collection',
      'resources[limit]': '8',
      'resources[limit_scope]': 'each',
      'resources[options][unavailable_products]': 'hide',
    });

    fetch(`${routes.predictive_search_url}?${searchParams.toString()}`, {
      signal: this.abortController.signal,
    })
      .then((response) => {
        if (!response.ok) {
          var error = new Error(response.status);
          this.close();
          throw error;
        }

        return response.text();
      })
      .then((text) => {
        const resultsMarkup = new DOMParser()
          .parseFromString(text, 'text/html')
          .querySelector('#shopify-section-predictive-search').innerHTML;
        // Save bandwidth keeping the cache in all instances synced
        this.allPredictiveSearchInstances.forEach((predictiveSearchInstance) => {
          predictiveSearchInstance.cachedResults[queryKey] = resultsMarkup;
        });
        this.renderSearchResults(resultsMarkup);
      })
      .catch((error) => {
        if (error?.code === 20) {
          // Code 20 means the call was aborted
          return;
        }
        this.close();
        throw error;
      });
  }

  setLiveRegionLoadingState() {
    this.statusElement = this.statusElement || this.querySelector('.predictive-search-status');
    this.loadingText = this.loadingText || this.getAttribute('data-loading-text');

    this.setLiveRegionText(this.loadingText);
    this.setAttribute('loading', true);
  }

  setLiveRegionText(statusText) {
    this.statusElement.setAttribute('aria-hidden', 'false');
    this.statusElement.textContent = statusText;

    setTimeout(() => {
      this.statusElement.setAttribute('aria-hidden', 'true');
    }, 1000);
  }

  renderSearchResults(resultsMarkup) {
    this.predictiveSearchResults.innerHTML = resultsMarkup;
    this.setAttribute('results', true);

    this.setLiveRegionResults();
    this.open();
  }

  setLiveRegionResults() {
    this.removeAttribute('loading');
    this.setLiveRegionText(this.querySelector('[data-predictive-search-live-region-count-value]').textContent);
  }

  getResultsMaxHeight() {
    const headerElement = document.querySelector('.section-header') || this.closest('.template-search__header');
    const bottomPosition = headerElement ? headerElement.getBoundingClientRect().bottom : 200;
    this.resultsMaxHeight = window.innerHeight - bottomPosition;
    return this.resultsMaxHeight;
  }

  open() {
    this.predictiveSearchResults.style.maxHeight = this.resultsMaxHeight || `${this.getResultsMaxHeight()}px`;
    this.setAttribute('open', true);
    this.input.setAttribute('aria-expanded', true);
    this.isOpen = true;
  }

  close(clearSearchTerm = false) {
    this.closeResults(clearSearchTerm);
    this.isOpen = false;
  }

  closeResults(clearSearchTerm = false) {
    if (clearSearchTerm) {
      this.input.value = '';
      this.removeAttribute('results');
    }
    const selected = this.querySelector('[aria-selected="true"]');

    if (selected) selected.setAttribute('aria-selected', false);

    this.input.setAttribute('aria-activedescendant', '');
    this.removeAttribute('loading');
    this.removeAttribute('open');
    this.input.setAttribute('aria-expanded', false);
    this.resultsMaxHeight = false;
    this.predictiveSearchResults.removeAttribute('style');
  }
}

customElements.define('predictive-search', PredictiveSearch);

document.addEventListener('DOMContentLoaded', function () {
  document.querySelectorAll('[id^="MainProduct-"][data-section]').forEach(function (productSection) {
    try {
      initDesktopProductMediaFlow(productSection);
    } catch (error) {
      console.error('Product desktop media flow init failed', error);
    }
  });

  document.querySelectorAll('[data-product-desktop-ux]').forEach(function (wrapper) {
    try {
      initProductDesktopUx(wrapper);
    } catch (error) {
      console.error('Product desktop UX init failed', error);
    }
  });
});

function initDesktopProductMediaFlow(productSection) {
  var sectionId = productSection.getAttribute('data-section');
  if (!sectionId) return;

  var desktopMediaQuery = window.matchMedia('(min-width: 990px)');
  var mediaWrapper = productSection.querySelector('.product__media-wrapper');
  var productInfo = document.getElementById('ProductInfo-' + sectionId);
  if (!mediaWrapper || !productInfo) return;

  var state = {
    active: false,
    maxOffset: 0,
    ticking: false,
  };

  var clearDesktopMediaFlow = function () {
    state.active = false;
    state.maxOffset = 0;
    productSection.classList.remove('product-section--desktop-media-flow');
    productSection.style.setProperty('--desktop-media-flow-offset', '0px');
  };

  var getDesktopMediaFlowAnchorOffset = function (mediaTop, mediaHeight, maxOffset) {
    var candidates = productSection.querySelectorAll(
      '[data-product-description], .product__accordion, product-recommendations, .product__view-details'
    );
    var gap = 24;

    for (var index = 0; index < candidates.length; index += 1) {
      var candidate = candidates[index];
      if (!candidate || candidate.offsetParent === null) continue;

      var candidateTop = candidate.getBoundingClientRect().top + window.scrollY;
      var candidateOffset = candidateTop - mediaTop - mediaHeight - gap;
      if (candidateOffset > 0) {
        return Math.min(maxOffset, candidateOffset);
      }
    }

    return maxOffset;
  };

  var syncDesktopMediaFlow = function () {
    if (!state.active) {
      productSection.style.setProperty('--desktop-media-flow-offset', '0px');
      return;
    }

    var offset = Math.min(window.scrollY, state.maxOffset);
    productSection.style.setProperty('--desktop-media-flow-offset', Math.max(offset, 0) + 'px');
  };

  var updateDesktopMediaFlow = function () {
    if (!desktopMediaQuery.matches) {
      clearDesktopMediaFlow();
      return;
    }

    var mediaHeight = Math.ceil(mediaWrapper.getBoundingClientRect().height);
    var infoHeight = Math.ceil(productInfo.getBoundingClientRect().height);
    if (!mediaHeight || !infoHeight) {
      clearDesktopMediaFlow();
      return;
    }

    var maxOffset = Math.max(0, infoHeight - mediaHeight - 24);
    var mediaTop = mediaWrapper.getBoundingClientRect().top + window.scrollY;
    maxOffset = getDesktopMediaFlowAnchorOffset(mediaTop, mediaHeight, maxOffset);

    if (maxOffset <= 24) {
      clearDesktopMediaFlow();
      return;
    }

    state.active = true;
    state.maxOffset = maxOffset;
    productSection.classList.add('product-section--desktop-media-flow');
    syncDesktopMediaFlow();
  };

  updateDesktopMediaFlow();

  if (typeof ResizeObserver === 'function') {
    var resizeObserver = new ResizeObserver(updateDesktopMediaFlow);
    resizeObserver.observe(mediaWrapper);
    resizeObserver.observe(productInfo);
  }

  if (typeof desktopMediaQuery.addEventListener === 'function') {
    desktopMediaQuery.addEventListener('change', updateDesktopMediaFlow);
  } else if (typeof desktopMediaQuery.addListener === 'function') {
    desktopMediaQuery.addListener(updateDesktopMediaFlow);
  }

  window.addEventListener('load', updateDesktopMediaFlow, { once: true });
  window.addEventListener('resize', updateDesktopMediaFlow);
  window.addEventListener('scroll', function () {
    if (state.ticking) return;

    state.ticking = true;
    window.requestAnimationFrame(function () {
      syncDesktopMediaFlow();
      state.ticking = false;
    });
  }, { passive: true });
}

function initProductDesktopUx(wrapper) {
  var sectionId = wrapper.getAttribute('data-section-id');
  if (!sectionId) return;

  var dataScript = document.getElementById('ProductMatchingSetData-' + sectionId);
  var productData = safeParseJson(dataScript && dataScript.textContent);
  if (!productData) return;

  initDeliveryHighlights(wrapper);
  initMatchingSizeGuide(wrapper, sectionId, productData);
  initMatchingSetBuilder(wrapper, sectionId, productData);
  initPhotoReviewPanel(wrapper);
  initDesktopStickyAtc(wrapper, sectionId);
}

function safeParseJson(value) {
  if (!value) return null;
  try {
    return JSON.parse(value);
  } catch (_error) {
    return null;
  }
}

function stripDiacritics(value) {
  var text = String(value || '');
  if (typeof text.normalize !== 'function') return text;
  return text.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function replaceLocaleDigits(value) {
  return String(value || '')
    .replace(/[٠-٩]/g, function (digit) {
      return String('٠١٢٣٤٥٦٧٨٩'.indexOf(digit));
    })
    .replace(/[۰-۹]/g, function (digit) {
      return String('۰۱۲۳۴۵۶۷۸۹'.indexOf(digit));
    });
}

function normalizeText(value) {
  return stripDiacritics(replaceLocaleDigits(value))
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ');
}

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function getOptionValue(variant, optionIndex) {
  return variant ? variant['option' + String(optionIndex + 1)] : '';
}

function formatMoney(cents, currency) {
  var locale = document.documentElement.getAttribute('lang') || undefined;
  try {
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: currency || 'USD',
      maximumFractionDigits: 2,
    }).format((Number(cents) || 0) / 100);
  } catch (_error) {
    return '$' + ((Number(cents) || 0) / 100).toFixed(2);
  }
}

function initDeliveryHighlights(wrapper) {
  wrapper.querySelectorAll('[data-desktop-estimate]').forEach(function (node) {
    var fallback = node.getAttribute('data-delivery-fallback') || node.textContent || '';
    node.textContent = fallback;
  });
}

