      }

      .curated-product-grid__footer {
        padding: 1.4rem 1.5rem;
      }

      .curated-product-grid__supporting-note {
        font-size: 1.25rem;
      }

      .curated-product-grid__footer-title {
        font-size: 1.9rem;
      }
    }
  {%- endstyle -%}

  <section
    class="curated-product-grid color-{{ section.settings.color_scheme }} gradient"
    {% if section_anchor_id != blank %}
      id="{{ section_anchor_id }}"
    {% endif %}
    data-analytics-list-id="curated-product-grid-{{ section.id }}"
    data-analytics-list-name="{{ section.settings.title | escape }}"
  >
    <div class="page-width section-{{ section.id }}-padding">
      <div class="curated-product-grid__header">
        <div class="curated-product-grid__heading-group">
          {%- if section.settings.title != blank -%}
            <h2 class="curated-product-grid__title inline-richtext {{ section.settings.heading_size }}">
              {%- if section.settings.button_link != blank -%}
                <a href="{{ section.settings.button_link }}" class="curated-product-grid__title-link">
                  {{ section.settings.title }}
                </a>
              {%- else -%}
                {{ section.settings.title }}
              {%- endif -%}
            </h2>
          {%- endif -%}
          {%- if section.settings.intro != blank -%}
            <div class="curated-product-grid__intro rte">
              {{ section.settings.intro }}
            </div>
          {%- endif -%}
          {%- if section.settings.supporting_note != blank -%}
            <div class="curated-product-grid__supporting-note rte">
              {{ section.settings.supporting_note }}
            </div>
          {%- endif -%}
        </div>

        {%- if section.settings.button_label != blank -%}
          <a
            class="button button--secondary"
            {% if section.settings.button_link != blank %}
              href="{{ section.settings.button_link }}"
            {% else %}
              role="link" aria-disabled="true"
            {% endif %}
          >
            {{ section.settings.button_label | escape }}
          </a>
        {%- endif -%}
      </div>

      <div class="curated-product-grid__grid">
        {%- for block in section.blocks -%}
          {%- if block.settings.product == blank -%}
            {%- continue -%}
          {%- endif -%}
          {%- liquid
            assign spotlight_fetchpriority = 'low'

            assign spotlight_static_theme_asset = blank
            assign spotlight_static_theme_asset_alt = blank
          -%}
          <div {{ block.shopify_attributes }}>
            {% render 'home-spotlight-card',
              spotlight_product: block.settings.product,
              spotlight_badge: block.settings.badge,
              spotlight_caption: block.settings.caption,
              spotlight_button_label: block.settings.button_label,
              spotlight_theme_asset: spotlight_static_theme_asset,
              spotlight_theme_asset_alt: spotlight_static_theme_asset_alt,
              spotlight_collection: block.settings.secondary_collection,
              spotlight_rotation_collection: block.settings.secondary_collection,
              spotlight_collection_link_label: block.settings.collection_link_label,
              lazy_load: true,
              spotlight_fetchpriority: spotlight_fetchpriority,
              section_id: section.id,
              image_sizes: '(min-width: 990px) 46vw, (min-width: 750px) 42vw, 92vw'
            %}
          </div>
        {%- endfor -%}
      </div>

      {%- if section.settings.footer_heading != blank or section.settings.footer_body != blank -%}
        <div class="curated-product-grid__footer">
          {%- if section.settings.footer_heading != blank -%}
            <h3 class="curated-product-grid__footer-title">{{ section.settings.footer_heading }}</h3>
          {%- endif -%}
          {%- if section.settings.footer_body != blank -%}
            <div class="curated-product-grid__footer-copy rte">
              {{ section.settings.footer_body }}
            </div>
          {%- endif -%}
        </div>
      {%- endif -%}
    </div>
  </section>
{%- endif -%}

{% schema %}
{
  "name": "Curated Product Grid",
  "tag": "section",
  "class": "section section-curated-product-grid",
  "disabled_on": {
    "groups": ["header", "footer"]
  },
  "settings": [
    {
      "type": "text",
      "id": "anchor_id",
      "label": "Anchor ID",
      "info": "Optional. Adds an HTML id for in-page links."
    },
    {
      "type": "text",
      "id": "title",
      "default": "Most-Loved Matching Sets",
      "label": "Title"
    },
    {
      "type": "select",
      "id": "heading_size",
      "options": [
        {
          "value": "h2",
          "label": "Small"
        },
        {
          "value": "h1",
          "label": "Medium"
        },
        {
          "value": "h0",
          "label": "Large"
        }
      ],
      "default": "h2",
      "label": "Heading size"
    },
    {
      "type": "richtext",
      "id": "intro",
      "label": "Intro"
    },
    {
      "type": "richtext",
      "id": "supporting_note",
      "label": "Condensed trust note"
    },
    {
      "type": "text",
      "id": "button_label",
      "default": "Shop all family sets",
      "label": "Button label"
    },
    {
      "type": "url",
      "id": "button_link",
      "label": "Button link"
    },
    {
      "type": "color_scheme",
      "id": "color_scheme",
      "default": "scheme-1",
      "label": "Color scheme"
    },
    {
      "type": "color",
      "id": "card_background",
      "default": "#FFFDFC",
      "label": "Card background"
    },
    {
      "type": "color",
      "id": "accent_color",
      "default": "#C87932",
      "label": "Accent color"
    },
    {
      "type": "text",
      "id": "footer_heading",
      "label": "Footer heading"
    },
    {
      "type": "richtext",
      "id": "footer_body",
      "label": "Footer body"
    },
    {
      "type": "range",
      "id": "padding_top",
      "min": 0,
      "max": 120,
      "step": 4,
      "default": 24,
      "unit": "px",
      "label": "Padding top"
    },
    {
      "type": "range",
      "id": "padding_bottom",
      "min": 0,
      "max": 120,
      "step": 4,
      "default": 32,
      "unit": "px",
      "label": "Padding bottom"
    }
  ],
  "blocks": [
    {
      "type": "product_card",
      "name": "Product card",
      "settings": [
        {
          "type": "product",
          "id": "product",
          "label": "Product"
        },
        {
          "type": "text",
          "id": "badge",
          "default": "Most loved",
          "label": "Badge"
        },
        {
          "type": "textarea",
          "id": "caption",
          "default": "Use this slot for the products shoppers engage with most before purchase.",
          "label": "Caption"
        },
        {
          "type": "text",
          "id": "button_label",
          "default": "Shop This Look",
          "label": "Button label"
        },
        {
          "type": "collection",
          "id": "secondary_collection",
          "label": "Secondary collection link"
        },
        {
          "type": "text",
          "id": "collection_link_label",
          "default": "See all matching looks",
          "label": "Secondary collection label"
        }
      ]
    }
  ],
  "max_blocks": 8,
  "presets": [
    {
      "name": "Curated Product Grid"
    }
  ]
}
{% endschema %}

{% comment %}theme-check-disable UndefinedObject{% endcomment %}
{{ 'section-footer.css' | asset_url | stylesheet_tag }}
{{ 'component-newsletter.css' | asset_url | stylesheet_tag }}
{{ 'component-list-menu.css' | asset_url | stylesheet_tag }}
{{ 'component-list-payment.css' | asset_url | stylesheet_tag }}
{{ 'component-list-social.css' | asset_url | stylesheet_tag }}
{{ 'cookie-preferences.css' | asset_url | stylesheet_tag }}
<script src="{{ 'cookie-preferences.js' | asset_url }}" defer="defer"></script>



<footer class="footer color-{{ section.settings.color_scheme }} gradient section-{{ section.id }}-padding">
  {%- liquid
    assign has_social_icons = true
    assign journal_blog = blogs['news']
    if settings.social_facebook_link == blank and settings.social_instagram_link == blank and settings.social_youtube_link == blank and settings.social_tiktok_link == blank and settings.social_twitter_link == blank and settings.social_pinterest_link == blank and settings.social_snapchat_link == blank and settings.social_tumblr_link == blank and settings.social_vimeo_link == blank
      assign has_social_icons = false
    endif

    if settings.brand_image == blank and settings.brand_headline == blank and settings.brand_description == blank
      assign brand_empty = true
    endif

    if section.blocks.size == 1 and section.blocks[0].type == 'brand_information' and brand_empty and has_social_icons == false and section.settings.newsletter_enable == false and section.settings.enable_follow_on_shop == false
      assign only_empty_brand = true
    endif
  -%}
  {%- if section.blocks.size > 0
    or section.settings.newsletter_enable
    or section.settings.show_social
    and has_social_icons == true
    or section.settings.enable_follow_on_shop
  -%}
    {%- unless only_empty_brand -%}
      <div class="footer__content-top page-width">
        {%- if section.blocks.size > 0 -%}
          {%- liquid
            if section.blocks.size == 9
              assign footer_grid_class = 'grid--3-col-tablet'
            elsif section.blocks.size > 6
              assign footer_grid_class = 'grid--4-col-desktop'
            elsif section.blocks.size > 4
              assign footer_grid_class = 'grid--3-col-tablet'
            endif
          -%}
          <div
            class="footer__blocks-wrapper grid grid--1-col grid--2-col grid--4-col-tablet {{ footer_grid_class }}{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
            {% if settings.animations_reveal_on_scroll %}
              data-cascade
            {% endif %}
          >
            {%- for block in section.blocks -%}
              <div
                class="footer-block grid__item{% if block.type == 'link_list' %} footer-block--menu{% endif %}{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
                {{ block.shopify_attributes }}
                {% if settings.animations_reveal_on_scroll %}
                  data-cascade
                  style="--animation-order: {{ forloop.index }};"
                {% endif %}
              >
                {%- if block.settings.heading != blank -%}
                  {%- assign footer_block_heading = block.settings.heading | strip -%}
                  {%- assign footer_block_heading_upcase = footer_block_heading | upcase -%}
                  {%- assign footer_block_heading_downcase = footer_block_heading | downcase -%}
                  {%- assign footer_locale = request.locale.iso_code | downcase -%}
                  <h2 class="footer-block__heading inline-richtext">
                    {%- if footer_locale contains 'es' and footer_block_heading_downcase contains 'encabezados_pie' and footer_block_heading_downcase contains 'informacion_empresa' -%}
                      Información de la empresa
                    {%- elsif footer_locale contains 'es' and footer_block_heading_downcase contains 'encabezados_pie' and footer_block_heading_downcase contains 'ayuda_soporte' -%}
                      Ayuda y soporte
                    {%- elsif footer_locale contains 'es' and footer_block_heading_downcase contains 'encabezados_pie' and footer_block_heading_downcase contains 'atención_al_cliente' -%}
                      Atención al cliente
                    {%- elsif footer_locale contains 'es' and footer_block_heading_downcase contains 'encabezados_pie' and footer_block_heading_downcase contains 'atencion_al_cliente' -%}
                      Atención al cliente
                    {%- elsif footer_block_heading contains 't:' -%}
                      {%- assign footer_translated_heading = footer_block_heading | remove_first: 't:' | t -%}
                      {%- if footer_locale contains 'es' and footer_translated_heading == 'Company info' -%}
                        Información de la empresa
                      {%- elsif footer_locale contains 'es' and footer_translated_heading == 'Help & support' -%}
                        Ayuda y soporte
                      {%- elsif footer_locale contains 'es' and footer_translated_heading == 'Customer care' -%}
                        Atención al cliente
                      {%- elsif footer_locale contains 'fr' and footer_translated_heading == 'Company info' -%}
                        Informations sur l'entreprise
                      {%- elsif footer_locale contains 'fr' and footer_translated_heading == 'Help & support' -%}
                        Aide et assistance
                      {%- elsif footer_locale contains 'fr' and footer_translated_heading == 'Customer care' -%}
                        Service client
                      {%- else -%}
                        {{ footer_translated_heading }}
                      {%- endif -%}
                    {%- elsif footer_block_heading_upcase == 'COMPANY INFO' -%}
                      {%- if footer_locale contains 'es' -%}
                        Información de la empresa
                      {%- elsif footer_locale contains 'fr' -%}
                        Informations sur l'entreprise
                      {%- else -%}
                        {{ 'sections.footer_headings.company_info' | t }}
                      {%- endif -%}
                    {%- elsif footer_block_heading_upcase == 'HELP & SUPPORT' -%}
                      {%- if footer_locale contains 'es' -%}
                        Ayuda y soporte
                      {%- elsif footer_locale contains 'fr' -%}
                        Aide et assistance
                      {%- else -%}
                        {{ 'sections.footer_headings.help_support' | t }}
                      {%- endif -%}
                    {%- elsif footer_block_heading_upcase == 'CUSTOMER CARE' -%}
                      {%- if footer_locale contains 'es' -%}
                        Atención al cliente
                      {%- elsif footer_locale contains 'fr' -%}
                        Service client
                      {%- else -%}
                        {{ 'sections.footer_headings.customer_care' | t }}
                      {%- endif -%}
                    {%- else -%}
                      {{- footer_block_heading -}}
                    {%- endif -%}
                  </h2>
                {%- endif -%}

                {%- case block.type -%}
                  {%- when '@app' -%}
                    {% render block %}
                  {%- when 'text' -%}
                    <div class="footer-block__details-content rte">
                      {{ block.settings.subtext }}
                    </div>
                  {%- when 'link_list' -%}
                    {%- if block.settings.menu != blank -%}
                      <ul class="footer-block__details-content list-unstyled">
                        {%- for link in block.settings.menu.links -%}
                          {%- assign footer_link_url = link.url | downcase -%}
                          {%- unless footer_link_url contains '/pages/size-guide' -%}
                            <li>
                              <a
                                href="{{ link.url }}"
                                class="link link--text list-menu__item list-menu__item--link{% if link.active %} list-menu__item--active{% endif %}"
                              >
                                {{ link.title }}
                              </a>
                            </li>
                          {%- endunless -%}
                        {%- endfor -%}
                      </ul>
                    {%- endif -%}
                  {%- when 'brand_information' -%}
                    <div class="footer-block__brand-info">
                      {%- if settings.brand_image != blank -%}
                        {%- assign brand_image_height = settings.brand_image_width
                          | divided_by: settings.brand_image.aspect_ratio
                        -%}
                        <div
                          class="footer-block__image-wrapper"
                          style="max-width: min(100%, {{ settings.brand_image_width }}px);"
                        >
                          {{
                            settings.brand_image
                            | image_url: width: 1100
                            | image_tag:
                              loading: 'lazy',
                              widths: '50, 100, 150, 200, 300, 400, 550, 800, 1100',
                              height: brand_image_height,
                              width: settings.brand_image_width
                          }}
                        </div>
                      {%- endif -%}
                      {%- if settings.brand_headline != blank -%}
                        <h2 class="footer-block__heading rte">{{ settings.brand_headline }}</h2>
                      {%- endif -%}
                      {%- if settings.brand_description != blank -%}
                        <div class="rte">{{ settings.brand_description }}</div>
                      {%- endif -%}
                      {%- if block.settings.show_social and has_social_icons -%}
                        {%- render 'social-icons', class: 'footer__list-social' -%}
                      {%- endif -%}
                    </div>
                  {%- when 'image' -%}
                    <div class="footer-block__details-content footer-block-image {{ block.settings.alignment }}">
                      {%- if block.settings.image != blank -%}
                        {%- assign image_size_2x = block.settings.image_width | times: 2 | at_most: 5760 -%}
                        <div
                          class="footer-block__image-wrapper"
                          style="max-width: min(100%, {{ block.settings.image_width }}px);"
                        >
                          <img
                            srcset="{{ block.settings.image | image_url: width: block.settings.image_width }}, {{ block.settings.image | image_url: width: image_size_2x }} 2x"
                            src="{{ block.settings.image | image_url: width: 760 }}"
                            alt="{{ block.settings.image.alt | escape }}"
                            loading="lazy"
                            width="{{ block.settings.image.width }}"
                            height="{{ block.settings.image.height }}"
                          >
                        </div>
                      {%- else -%}
                        {{ 'image' | placeholder_svg_tag: 'placeholder-svg placeholder' }}
                      {%- endif -%}
                    </div>
                {%- endcase -%}
              </div>
            {%- endfor -%}
          </div>
        {%- endif -%}

        {%- comment -%}
          CRO: removed the footer "Do we ship to my country?" block.
          The same modal is already reachable from the product page via the
          inline "See all current shipping countries" link inside the
          "Shipping & Delivery" panel — surfacing it again sitewide in the
          footer was duplicative and visually heavy.
        {%- endcomment -%}

        {%- if journal_blog != blank and section.settings.show_journal_link -%}
          {%- liquid
            assign footer_journal_label = section.settings.journal_link_label | default: 'Style Journal'
            assign footer_journal_summary = 'Family fashion tips, matching outfit ideas, and seasonal style guides.'
            assign footer_journal_cta_prefix = 'Read the '
            if footer_locale contains 'es'
              assign footer_journal_summary = 'Consejos de moda familiar, ideas de conjuntos a juego y guías de estilo de temporada.'
              assign footer_journal_cta_prefix = 'Leer el '
            endif
          -%}
          <div class="footer-block grid__item footer-block--journal{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
            <h2 class="footer-block__heading inline-richtext">{{ footer_journal_label }}</h2>
            <div class="footer-block__details-content rte">
              <p>{{ footer_journal_summary }}</p>
              <a href="{{ journal_blog.url }}" class="link link--text list-menu__item list-menu__item--link">
                {{ footer_journal_cta_prefix }}{{ footer_journal_label }} &rarr;
              </a>
            </div>
          </div>
        {%- endif -%}

        <div
          class="footer-block--newsletter{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
          {% if settings.animations_reveal_on_scroll %}
            data-cascade
          {% endif %}
        >
          {%- if section.settings.newsletter_enable -%}
            <div class="footer-block__newsletter">
              {%- if section.settings.newsletter_heading != blank -%}
                <h2 class="footer-block__heading inline-richtext">{{ section.settings.newsletter_heading }}</h2>
              {%- endif -%}
              {%- form 'customer', id: 'ContactFooter', class: 'footer__newsletter newsletter-form' -%}
                <input type="hidden" name="contact[tags]" value="newsletter,footer-signup">
                <div class="newsletter-form__field-wrapper">
                  <div class="field">
                    <input
                      id="NewsletterForm--{{ section.id }}"
                      type="email"
                      name="contact[email]"
                      class="field__input"
                      value="{{ form.email }}"
                      aria-required="true"
                      autocorrect="off"
                      autocapitalize="off"
                      autocomplete="email"
                      {% if form.errors %}
                        autofocus
                        aria-invalid="true"
                        aria-describedby="ContactFooter-error"
                      {% elsif form.posted_successfully? %}
                        aria-describedby="ContactFooter-success"
                      {% endif %}
                      placeholder="{{ 'newsletter.label' | t }}"
                      required
                    >
                    <label class="field__label" for="NewsletterForm--{{ section.id }}">
                      {{ 'newsletter.label' | t }}
                    </label>
                    <button
                      type="submit"
                      class="newsletter-form__button field__button"
                      name="commit"
                      id="Subscribe"
                      aria-label="{{ 'newsletter.button_label' | t }}"
                    >
                      {% render 'icon-arrow' %}
                    </button>
                  </div>
                  {%- if form.errors -%}
                    <small
                      class="newsletter-form__message form__message"
                      id="ContactFooter-error"
                      data-analytics-newsletter-state="error"
                    >
                      {%- render 'icon-error' -%}
                      {{- form.errors.translated_fields.email | capitalize }}
                      {{ form.errors.messages.email -}}
                    </small>
                  {%- endif -%}
                </div>
                {%- if form.posted_successfully? -%}
                  <h3
                    class="newsletter-form__message newsletter-form__message--success form__message"
                    id="ContactFooter-success"
                    tabindex="-1"
                    autofocus
                    data-analytics-newsletter-state="success"
                  >
                    {% render 'icon-success' %}
                    {{- 'newsletter.success' | t }}
                  </h3>
                {%- endif -%}
              {%- endform -%}
            </div>
          {%- endif -%}

          {%- if shop.features.follow_on_shop? and section.settings.enable_follow_on_shop -%}
            <div class="footer__follow-on-shop">
              {% comment %} TODO: enable theme-check once `login_button` is accepted as valid filter {% endcomment %}
              {% # theme-check-disable %}
              {{ shop | login_button: action: 'follow' }}
              {% # theme-check-enable %}
            </div>
          {%- endif -%}

          {%- if section.settings.show_social and has_social_icons -%}
            {%- render 'social-icons', class: 'footer__list-social' -%}
          {%- endif -%}
        </div>
      </div>
    {%- endunless -%}
  {%- endif -%}

  <div
    class="footer__content-bottom{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
    {% if settings.animations_reveal_on_scroll %}
      data-cascade
    {% endif %}
  >
    <div class="footer__content-bottom-wrapper page-width">
      <div class="footer__column footer__localization isolate">
        {%- if section.settings.enable_country_selector and localization.available_countries.size > 1 -%}
          <localization-form>
            {%- form 'localization', id: 'FooterCountryForm', class: 'localization-form' -%}
              <div>
                <h2 class="caption-large text-body" id="FooterCountryLabel">{{ 'localization.country_label' | t }}</h2>
                {%- render 'country-localization', localPosition: 'FooterCountry' -%}
              </div>
            {%- endform -%}
          </localization-form>
        {%- endif -%}

        {%- if section.settings.enable_language_selector and localization.available_languages.size > 1 -%}
          <localization-form>
            {%- form 'localization', id: 'FooterLanguageForm', class: 'localization-form' -%}
              <div>
                <h2 class="caption-large text-body" id="FooterLanguageLabel">
                  {{ 'localization.language_label' | t }}
                </h2>
                {%- render 'language-localization', localPosition: 'FooterLanguage' -%}
              </div>
            {%- endform -%}
          </localization-form>
        {%- endif -%}
      </div>
      <div class="footer__column footer__column--info">
        {%- if section.settings.payment_enable -%}
          <div class="footer__payment">
            <span class="visually-hidden">{{ 'sections.footer.payment' | t }}</span>
            <ul class="list list-payment" role="list">
              {%- for type in shop.enabled_payment_types -%}
                <li class="list-payment__item">
                  {{ type | payment_type_svg_tag: class: 'icon icon--full-color' }}
                </li>
              {%- endfor -%}
            </ul>
          </div>
        {%- endif -%}
      </div>
    </div>
    <div class="footer__content-bottom-wrapper page-width{% if section.settings.enable_country_selector == false and section.settings.enable_language_selector == false %} footer__content-bottom-wrapper--center{% endif %}">
      <div class="footer__copyright caption">
        <small class="copyright__content">&copy; {{ 'now' | date: '%Y' }}, {{ shop.name | link_to: routes.root_url -}}</small>
        {%- if section.settings.show_policy -%}
          <ul class="policies list-unstyled">
            {%- for policy in shop.policies -%}
              {%- if policy != blank -%}
                <li>
                  <small class="copyright__content"><a href="{{ policy.url }}">{{ policy.title }}</a></small>
                </li>
              {%- endif -%}
            {%- endfor -%}
            {%- if journal_blog != blank and section.settings.show_journal_link -%}
              <li>
                <small class="copyright__content"><a href="{{ journal_blog.url }}">{{ section.settings.journal_link_label | escape }}</a></small>
              </li>
            {%- endif -%}
          </ul>
        {%- elsif journal_blog != blank and section.settings.show_journal_link -%}
          <small class="copyright__content"><a href="{{ journal_blog.url }}">{{ section.settings.journal_link_label | escape }}</a></small>
        {%- endif -%}
        <cookie-preferences
          class="footer__cookie-preferences"
          data-unavailable-message="{{ 'sections.footer.cookie_preferences_unavailable' | t | escape }}"
        >
          <button
            type="button"
            class="link link--text footer__cookie-preferences-button"
            aria-haspopup="dialog"
            aria-describedby="CookiePreferencesStatus-{{ section.id }}"
          >
            {{ 'sections.footer.cookie_preferences' | t | escape }}
          </button>
          <span
            id="CookiePreferencesStatus-{{ section.id }}"
            class="footer__cookie-preferences-status"
            role="status"
            aria-live="polite"
            aria-atomic="true"
          ></span>
        </cookie-preferences>
      </div>
    </div>
  </div>
</footer>

